247	/**
248	 * Subscription sweep, run periodically by the worker:
249	 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
250	 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
251	 *                                                 saved card for the remainder
252	 *  - card declined                             -> dunning (retry days 1/3/5 + email)
253	 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
254	 * Free servers (isFree) are never touched.
255	 */
256	export async function billingSweep() {
257	  const now = new Date();
258	  const cfg = await dunningConfig();
259	  const prices = {
260	    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
261	    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
262	    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
263	    // upsell keeps billing every cycle rather than being a one-off charge.
264	    extraDiskPerGbCents: await extraDiskPerGbCents(),
265	    // Monthly price of the Plus backup-retention tier. A server on Plus renews at
266	    // plan + this x months, folded into totalCents by renewalCharge exactly like
267	    // the extra-disk line, so the retention upsell keeps billing every cycle.
268	    backupPlusCents: await backupPlusMonthlyCents(),
269	    // The admin ANNUAL discount. A 12-month server renews at this rate — the same
270	    // one it was ordered and displayed at — so an annual subscription renews for
271	    // another year at the SAME annual price. Ignored for every other term.
272	    annualDiscountPct: await annualDiscountPct(),
273	  };
274	  // Seller country + global fallback rate, read ONCE per sweep. The per-server VAT
275	  // rate is resolved (purely) from each owner's billing country against these, so the
276	  // renewal charge, the card leg and the invoice all carry the same tax the customer
277	  // is shown elsewhere (Finding 1).
278	  const taxParams = { sellerCountry: await sellerCountry(), fallbackPercent: await taxRate() };
279	  // Off by default — see the setting's own doc comment in lib/settings.ts.
280	  const paypalFallbackEnabled = await getSettingBool("renewals_paypal_fallback_enabled", false);
281	  const taxCtxFor = (u: { billingCountry?: string | null; vatId?: string | null }): TaxContext =>
282	    resolveCountryTaxRate({
283	      country: u.billingCountry ?? null,
284	      vatId: u.vatId ?? null,
285	      sellerCountry: taxParams.sellerCountry,
286	      fallbackPercent: taxParams.fallbackPercent,
287	    });
288	
289	  // Claim any card that was saved at Stripe but never confirmed in the browser,
290	  // BEFORE the renewal queries read card state — otherwise a customer who closed
291	  // the tab on Stripe's page gets dunned for a card we simply failed to record.
292	  try {
293	    const adopted = await adoptUnclaimedCards(now);
294	    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
295	  } catch (e) {
296	    console.error("[billing] card adoption error", e);
297	  }
298	
299	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
300	  const soon = new Date(now.getTime() + 3 * 86400_000);
301	  const upcoming = await db.server.findMany({
302	    where: {
303	      isFree: false,
304	      expiresAt: { gt: now, lt: soon },
305	      status: { in: ["RUNNING", "STOPPED"] },
306	    },
307	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
308	  });
309	  for (const server of upcoming) {
310	    // Tax-inclusive so the "renewal is $X" warning matches what the sweep will take.
311	    const warnCents = renewalCharge(server, { ...prices, taxRatePercent: taxCtxFor(server.user).ratePercent }).totalCents;
312	    // A customer with a card (or, when enabled, a vaulted PayPal method) on
313	    // file needs no warning and no top-up: the renewal applies their wallet
314	    // credit and auto-charges the remainder. Telling them to "top up to avoid
315	    // suspension" would raise an alarm about a suspension that is not going
316	    // to happen.
317	    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableRenewalMethod(server.user, paypalFallbackEnabled))) {
318	      continue;
319	    }

